def sol(text):
    answer = ''
    i = 0
    while i < len(text):
        j = i + 1
        while j < len(text) and text[j] == text[i]:
            j += 1
        answer += text[i] + str(j - i)
        i = j
    return answer

def sol(text, k):
    if not text:
        return text
    k %= len(text)
    return text[k:] + text[:k]

def sol(text):
