def sol(width, height, commands):
    x = y = 0
    for c in commands:
        dx, dy = {'U': (0, 1), 'D': (0, -1), 'L': (-1, 0), 'R': (1, 0)}[c]
        nx, ny = x + dx, y + dy
        if 0 <= nx < width and 0 <= ny < height:
            x, y = nx, ny
    return [x, y]

def sol(hour, minute, added):
    total = (hour * 60 + minute + added) % 1440
    return [total // 60, total % 60]

def sol(month, day):
