def sol(start, moves):
    floor = start
    for move in moves:
        floor += move
    return floor

def sol(start, minimum, maximum, moves):
    floor = start
    for move in moves:
        candidate = floor + move
        if minimum <= candidate <= maximum:
            floor = candidate
    return floor

