def sol(first, second):
    if first == second:
        return 0
    return 1 if (first, second) in [('rock', 'scissors'), ('scissors', 'paper'), ('paper', 'rock')] else 2

def sol(first, second):
    wins = [0, 0]
    for a, b in zip(first, second):
        if a == b:
            continue
        winner = 0 if (a, b) in [('rock', 'scissors'), ('scissors', 'paper'), ('paper', 'rock')] else 1
        wins[winner] += 1
    return wins

def sol(start, changes):
