    return sum(matrix[r][c] for r in range(rows) for c in range(cols) if r in (0, rows - 1) or c in (0, cols - 1))

def sol(matrix):
    sums = [sum(row) for row in matrix]
    return sums.index(max(sums))

def sol(matrix):
